201	/****************************************************************************
202	 * Name: ana_setbit
203	 *
204	 * Description:
205	 *   Read-modify-write a single bitfield in an analog register via
206	 *   ana_write (with SPI completion poll).
207	 *
208	 ****************************************************************************/
209	
210	static void ana_setbit(uintptr_t addr, int pos, uint32_t val)
211	{
212	  uint32_t r = aud_getreg(addr);
213	
214	  r &= ~(1u << pos);
215	  r |= ((val & 1u) << pos);
216	  ana_write(addr, r);
217	}
