221	 ****************************************************************************/
222	
223	/****************************************************************************
224	 * Name: audio_init
225	 *
226	 * Description:
227	 *   Initialise BK7258 audio ADC for dual-channel differential capture
228	 *   at 16 kHz.  Sequence from Armino:
229	 *     aud_common_driver.c: bk_aud_driver_init()
230	 *     aud_adc_driver.c:    bk_aud_adc_init()
231	 *     sys_ll.h:            analog SPI write helpers
232	 *
233	 ****************************************************************************/
234	
235	static void audio_init(void)
236	{
237	  uint32_t val;
238	
239	  /* ---- Step -1: Audio power domain ----
240	   * cpu_power_sleep_wakeup bit6 pwd_audp: 0 = power on.
241	   * Must be first — without this the audio rail is off and
242	   * nothing else takes effect.
243	   */
244	
245	  val = aud_getreg(SYS_CPU_POWER_SLEEP_WAKEUP);
246	  val &= ~SYS_PWD_AUDP;
247	  aud_putreg(val, SYS_CPU_POWER_SLEEP_WAKEUP);
248	  up_mdelay(2);
249	
250	  syslog(LOG_INFO,
251	         "[mic] PWR: POWER_SLEEP_WAKEUP=0x%08lx\n",
252	         (unsigned long)aud_getreg(SYS_CPU_POWER_SLEEP_WAKEUP));
253	
254	  /* ---- Step 0: SYS audio clock ----
255	   * Must be done BEFORE any AUD 0x478xxxxx register access.
256	   * cksel_aud = 0 (XTAL 26 MHz), aud_cken = 1.
257	   */
258	
259	  val = aud_getreg(SYS_CPU_CLK_DIV_MODE1);
260	  val &= ~SYS_CKSEL_AUD;
261	  aud_putreg(val, SYS_CPU_CLK_DIV_MODE1);
262	
263	  val = aud_getreg(SYS_CPU_DEVICE_CLK_ENABLE);
264	  val |= SYS_AUD_CKEN;
265	  aud_putreg(val, SYS_CPU_DEVICE_CLK_ENABLE);
266	
267	  syslog(LOG_INFO,
268	         "[mic] SYS aud clock: DIV=0x%08lx CLK=0x%08lx\n",
269	         (unsigned long)aud_getreg(SYS_CPU_CLK_DIV_MODE1),
270	         (unsigned long)aud_getreg(SYS_CPU_DEVICE_CLK_ENABLE));
271	
272	  /* ---- Step 1: AUD digital soft reset ---- */
273	
274	  val = aud_getreg(AUD_CLK_CONTROL);
275	  val &= ~AUD_ADC_CLK_GATE;
276	  aud_putreg(val, AUD_CLK_CONTROL);
277	
278	  val = aud_getreg(AUD_CLK_CONTROL);
279	  val |= AUD_ADC_SOFT_RESET;
280	  aud_putreg(val, AUD_CLK_CONTROL);
281	  up_mdelay(1);
282	  val &= ~AUD_ADC_SOFT_RESET;
283	  aud_putreg(val, AUD_CLK_CONTROL);
284	
285	  /* ---- Step 2: Analog register base values ----
286	   * Must go through analog-SPI (ana_write), NOT raw putreg32.
287	   * These carry trim fields from Armino *_DEFAULT_VAL computation.
288	   */
289	
290	  syslog(LOG_INFO, "[mic] ana: writing base values\n");
291	
292	  ana_write(ANA_REG18, ANA_REG18_BASE);
293	  ana_write(ANA_REG19, ANA_REG19_BASE);
294	  ana_write(ANA_REG20, ANA_REG20_BASE);
295	  ana_write(ANA_REG21, ANA_REG21_BASE);
296	  ana_write(ANA_REG27, ANA_REG27_BASE);
297	
298	  /* ---- Step 3: Enable analog bias + mic enables ----
299	   * Each setbit goes through ana_write with SPI poll.

300	   * Armino: aud_adc_driver.c lines 101-106.
301	   */
302	
303	  syslog(LOG_INFO, "[mic] ana: enable bias + mic1 + mic2\n");
304	
305	  /* audbias / adcbias / micbias on ana_reg18 */
306	
307	  ana_setbit(ANA_REG18, ANA_ENAUDBIAS_BIT, 1);
308	  ana_setbit(ANA_REG18, ANA_ENADCBIAS_BIT, 1);
309	  ana_setbit(ANA_REG18, ANA_ENMICBIAS_BIT, 1);
310	
311	  /* mic1 enable on ana_reg19 bit28 */
312	
313	  ana_setbit(ANA_REG19, ANA_MICEN_BIT, 1);
314	
315	  /* mic2 enable on ana_reg27 bit28.
316	   * (sys_hal_aud_mic2_en is "not support" — write full word.)
317	   */
318	
319	  ana_setbit(ANA_REG27, ANA_MICEN_BIT, 1);
320	
321	  /* Differential mode: ana_reg19 micsingleen=0 (already 0 in base),
322	   * ana_reg20 diffen=1 (already 1 in base).
323	   * No extra writes needed.
324	   */
325	
326	  /* ---- Step 4: MIC reset pulse ---- */
327	
328	  syslog(LOG_INFO, "[mic] ana: mic reset\n");
329	
330	  ana_setbit(ANA_REG19, ANA_MIC_RST_BIT, 1);
331	  up_mdelay(10);
332	  ana_setbit(ANA_REG19, ANA_MIC_RST_BIT, 0);
333	
334	  /* ---- Step 5: ADC digital config ---- */
335	
336	  syslog(LOG_INFO, "[mic] digital: ADC config\n");
337	
338	  val = aud_getreg(AUD_ADC_CONFIG_0);
339	  val &= ~(AUD_ADC_GAIN_MASK | AUD_ADC_EDGE);
340	  val |= AUD_ADC_GAIN_0DB;
341	  val |= AUD_ADC_HPF1_BYP | AUD_ADC_HPF2_BYP;
342	  aud_putreg(val, AUD_ADC_CONFIG_0);
343	
344	  /* ---- Step 6: Sample rate 16kHz, XTAL ---- */
345	
346	  val = aud_getreg(AUD_CONFIG);
347	  val &= ~(AUD_RATE_ADC_MASK | AUD_APLL_SEL);
348	  val |= AUD_RATE_ADC_16K;
349	  aud_putreg(val, AUD_CONFIG);
350	
351	  val = aud_getreg(AUD_EXTEND_CFG);
352	  val &= ~AUD_ADC_FRAC_MANUAL;
353	  aud_putreg(val, AUD_EXTEND_CFG);
354	
355	  /* ---- Step 7: Enable ADC + analog input path ----
356	   * Armino bk_aud_adc_start: adc_enable and line_enable
357	   * are set together.  line_enable is the analog ADC input
358	   * path enable, NOT an external line-in selector.
359	   */
360	
361	  syslog(LOG_INFO, "[mic] digital: ADC enable\n");
362	
363	  val = aud_getreg(AUD_CONFIG);
364	  val |= AUD_ADC_ENABLE | AUD_LINEIN_ENABLE;
365	  aud_putreg(val, AUD_CONFIG);
366	
367	  up_mdelay(50);
368	
369	  /* Diagnostic readback */
370	
371	  syslog(LOG_INFO,
372	         "[mic] init done. ana_reg readback:\n"
373	         "  reg18=0x%08lx reg19=0x%08lx\n"
374	         "  reg20=0x%08lx reg27=0x%08lx\n"
375	         "  AUD_CONFIG=0x%08lx\n",
376	         (unsigned long)aud_getreg(ANA_REG18),
377	         (unsigned long)aud_getreg(ANA_REG19),
378	         (unsigned long)aud_getreg(ANA_REG20),
379	         (unsigned long)aud_getreg(ANA_REG27),
380	         (unsigned long)aud_getreg(AUD_CONFIG));
381	}
