112	 * Private Functions
113	 ****************************************************************************/
114	
115	/****************************************************************************
116	 * Name: gpio_set_output
117	 ****************************************************************************/
118	
119	static void gpio_set_output(int pin)
120	{
121	  uint32_t cfg = getreg32(BK7258_GPIO_CFG(pin));
122	
123	  cfg &= ~GPIO_CFG_SECOND_FUNC;  /* GPIO mode (bit6 = 0) */
124	  cfg &= ~GPIO_CFG_OUTPUT_EN;    /* output enable (bit3 active-low: 0 = on) */
125	  cfg &= ~GPIO_CFG_INPUT_EN;     /* input off (bit2: 0=off) */
126	  putreg32(cfg, BK7258_GPIO_CFG(pin));
127	}
