129	/****************************************************************************
130	 * Name: gpio_write
131	 ****************************************************************************/
132	
133	static void gpio_write(int pin, int val)
134	{
135	  uint32_t cfg = getreg32(BK7258_GPIO_CFG(pin));
136	
137	  if (val)
138	    {
139	      cfg |= GPIO_CFG_OUTPUT;
140	    }
141	  else
142	    {
143	      cfg &= ~GPIO_CFG_OUTPUT;
144	    }
145	
146	  putreg32(cfg, BK7258_GPIO_CFG(pin));
147	}
