172	/****************************************************************************
173	 * Name: spi_write_byte
174	 ****************************************************************************/
175	
176	static void spi_write_byte(uint8_t byte)
177	{
178	  int bit;
179	
180	  for (bit = 7; bit >= 0; bit--)
181	    {
182	      gpio_write(g_active_pins->mosi, (byte >> bit) & 1);
183	      spi_delay();
184	      gpio_write(g_active_pins->sclk, 1);
185	      spi_delay();
186	      gpio_write(g_active_pins->sclk, 0);
187	    }
188	}
