410	/****************************************************************************
411	 * Name: lcd_fill_circle
412	 *
413	 * Description:
414	 *   Fill a circle centred at (cx,cy) with radius r using scanline
415	 *   rendering.  Each scanline is a 1px-high lcd_fill_rect call.
416	 *
417	 ****************************************************************************/
418	
419	static void lcd_fill_circle(int16_t cx, int16_t cy, int16_t r,
420	                            uint16_t color)
421	{
422	  int16_t y;
423	  int16_t dx;
424	  int16_t x0;
425	  int16_t x1;
426	  int32_t r2 = (int32_t)r * r;
427	
428	  for (y = cy - r; y <= cy + r; y++)
429	    {
430	      int32_t dy  = (int32_t)(y - cy);
431	      int32_t rem = r2 - dy * dy;
432	
433	      if (rem < 0)
434	        {
435	          continue;
436	        }
437	
438	      dx = sqrt_int(rem);
439	      x0 = cx - dx;
440	      x1 = cx + dx;
441	
442	      if (x0 < 0)
443	        {
444	          x0 = 0;
445	        }
446	
447	      if (x1 >= LCD_WIDTH)
448	        {
449	          x1 = LCD_WIDTH - 1;
450	        }
451	
452	      if (y < 0 || y >= LCD_HEIGHT)
453	        {
454	          continue;
455	        }
456	
457	      lcd_fill_rect(x0, y, x1, y, color);
458	    }
459	}
