461	/****************************************************************************
462	 * Name: lcd_fill_round_rect
463	 *
464	 * Description:
465	 *   Fill a rounded rectangle centred at (cx,cy), width w, height h,
466	 *   corner radius r.  Built from one inner rect + four corner circles.
467	 *
468	 ****************************************************************************/
469	
470	static void lcd_fill_round_rect(int16_t cx, int16_t cy,
471	                                int16_t w, int16_t h,
472	                                int16_t r, uint16_t color)
473	{
474	  int16_t x0 = cx - w / 2;
475	  int16_t y0 = cy - h / 2;
476	  int16_t x1 = cx + w / 2;
477	  int16_t y1 = cy + h / 2;
478	
479	  /* Horizontal centre strip (full width, reduced height) */
480	
481	  lcd_fill_rect(x0, y0 + r, x1, y1 - r, color);
482	
483	  /* Vertical centre strip (reduced width, full height) */
484	
485	  lcd_fill_rect(x0 + r, y0, x1 - r, y1, color);
486	
487	  /* Four corner circles */
488	
489	  lcd_fill_circle(x0 + r, y0 + r, r, color);
490	  lcd_fill_circle(x1 - r, y0 + r, r, color);
491	  lcd_fill_circle(x0 + r, y1 - r, r, color);
492	  lcd_fill_circle(x1 - r, y1 - r, r, color);
493	}
