429	/****************************************************************************
430	 * Name: audio_capture
431	 *
432	 * Description:
433	 *   Poll ADC FIFO and capture N sample pairs (L+R interleaved).
434	 *   Each AUD_ADC_FIFO_PORT read returns L in [15:0], R in [31:16].
435	 *   Times out with diagnostics if FIFO stays empty.
436	 *
437	 ****************************************************************************/
438	
439	static int audio_capture(int n)
440	{
441	  int count = 0;
442	  uint32_t status;
443	  uint32_t sample;
444	  uint32_t spin_sample;
445	  uint32_t spin_total = 0;
446	
447	  syslog(LOG_INFO, "[mic] capturing %d samples ...\n", n);
448	
449	  while (count < n)
450	    {
451	      spin_sample = 0;
452	
453	      for (;;)
454	        {
455	          status = aud_getreg(AUD_FIFO_STATUS);
456	
457	          if (!(status & AUD_ADC_FIFO_EMPTY))
458	            {
459	              break;
460	            }
461	
462	          if (++spin_sample >= FIFO_SPIN_LIMIT)
463	            {
464	              goto timeout;
465	            }
466	        }
467	
468	      sample = aud_getreg(AUD_ADC_FIFO_PORT);
469	      g_mic_left[count]  = (int16_t)(sample & 0xffff);
470	      g_mic_right[count] = (int16_t)((sample >> 16) & 0xffff);
471	      count++;
472	
473	      spin_total += spin_sample;
474	
475	      if (spin_total >= TOTAL_SPIN_CAP)
476	        {
477	          goto timeout;
478	        }
479	    }
480	
481	  syslog(LOG_INFO, "[mic] capture done: %d pairs\n", count);
482	  return count;
483	
484	timeout:
485	  syslog(LOG_ERR,
486	         "[mic] TIMEOUT after %d pairs\n"
487	         "  AUD_FIFO_STATUS = 0x%08lx\n"
488	         "  AUD_CONFIG      = 0x%08lx\n"
489	         "  ana_reg18       = 0x%08lx\n"
490	         "  ana_reg19       = 0x%08lx\n"
491	         "  ana_reg27       = 0x%08lx\n"
492	         "  SPI_STATE       = 0x%08lx\n"
493	         "  PWR_SLEEP_WAKE  = 0x%08lx\n",
494	         count,
495	         (unsigned long)aud_getreg(AUD_FIFO_STATUS),
496	         (unsigned long)aud_getreg(AUD_CONFIG),
497	         (unsigned long)aud_getreg(ANA_REG18),
498	         (unsigned long)aud_getreg(ANA_REG19),
499	         (unsigned long)aud_getreg(ANA_REG27),
500	         (unsigned long)aud_getreg(ANA_SPI_STATE_REG),
501	         (unsigned long)aud_getreg(SYS_CPU_POWER_SLEEP_WAKEUP));
502	  return count;
503	}
