505	/****************************************************************************
506	 * Name: compute_rms
507	 *
508	 * Description:
509	 *   Compute RMS of an int16_t buffer.
510	 *
511	 ****************************************************************************/
512	
513	static float compute_rms(const int16_t *buf, int n)
514	{
515	  double sum = 0.0;
516	  int i;
517	
518	  for (i = 0; i < n; i++)
519	    {
520	      sum += (double)buf[i] * (double)buf[i];
521	    }
522	
523	  return (float)sqrt(sum / n);
524	}
