/****************************************************************************
 * Name: bk7258_mic_locate
 *
 * Description:
 *   Capture stereo audio and estimate sound direction via time-domain
 *   cross-correlation.  Returns direction dx (-22/0/+22) and writes
 *   the fractional sample delay τ in Q8 fixed-point to *out_tau_q8.
 *
 *   Algorithm:
 *     a) Capture L[N]/R[N] (int16).
 *     b) Remove DC offset (subtract per-channel mean).
 *     c) Energy gate: if both RMS < RMS_GATE → centered, τ=0.
 *     d) Normalised cross-correlation for lag d ∈ [-D, +D].
 *     e) Parabolic interpolation around peak for sub-sample τ.
 *     f) Map: |τ| < TAU_DEAD → center; else ±22 by sign.
 *
 * Input Parameters:
 *   out_tau_q8 - pointer to receive τ in Q8 (τ * 256), may be NULL.
 *
 * Returned Value:
 *   dx: DX_LEFT (-22), DX_CENTER (0), or DX_RIGHT (+22).
 *
 ****************************************************************************/

int bk7258_mic_locate(int *out_tau_q8)
{
  int n;
  int i;
  int d;
  int best_d = 0;
  int32_t mean_l = 0;
  int32_t mean_r = 0;
  int32_t energy_l = 0;
  int32_t energy_r = 0;
  int16_t rms_l;
  int16_t rms_r;
  int32_t best_corr;
  int32_t corr_prev;
  int32_t corr_best;
  int32_t corr_next;
  int32_t denom;
  int32_t tau_q8;
  int dx;

  /* a) Capture */

  audio_init();
  n = audio_capture(MIC_N_SAMPLES);
  audio_deinit();

  if (n < 64)
    {
      syslog(LOG_ERR, "[hear] capture too short: %d\n", n);
      if (out_tau_q8)
        {
          *out_tau_q8 = 0;
        }

      return DX_CENTER;
    }

  /* b) Remove DC offset — compute mean then subtract */

  for (i = 0; i < n; i++)
    {
      mean_l += g_mic_left[i];
      mean_r += g_mic_right[i];
    }

  mean_l /= n;
  mean_r /= n;

  for (i = 0; i < n; i++)
    {
      g_mic_left[i]  = (int16_t)(g_mic_left[i]  - mean_l);
      g_mic_right[i] = (int16_t)(g_mic_right[i] - mean_r);
    }

  /* Compute RMS for energy gate and reporting */

  for (i = 0; i < n; i++)
    {
      int32_t sl = g_mic_left[i];
      int32_t sr = g_mic_right[i];

      energy_l += sl * sl;
      energy_r += sr * sr;
    }

  /* Integer RMS: sqrt(energy/n).  Use shift-approx for speed. */

  {
    int32_t vl = energy_l / n;
    int32_t vr = energy_r / n;
    int16_t rl = 0;
    int16_t rr = 0;
    int bit;

    for (bit = 15; bit >= 0; bit--)
      {
        int32_t t;

        t = rl + (1 << bit);
        if (t * t <= vl)
          {
            rl = (int16_t)t;
          }

        t = rr + (1 << bit);
        if (t * t <= vr)
          {
            rr = (int16_t)t;
          }
      }

    rms_l = rl;
    rms_r = rr;
  }

  syslog(LOG_INFO,
         "[hear] RMS: L=%d R=%d (gate=%d)\n",
         rms_l, rms_r, RMS_GATE);

  /* c) Energy gate — silence → centered */

  if (rms_l < RMS_GATE && rms_r < RMS_GATE)
    {
      syslog(LOG_INFO,
             "[hear] silent → center, tau=0\n");
      if (out_tau_q8)
        {
          *out_tau_q8 = 0;
        }

      return DX_CENTER;
    }

  /* d) Cross-correlation, lag d ∈ [-CORR_LAG_MAX, +CORR_LAG_MAX]
   *    corr(d) = Σ L[i] * R[i - d]   for valid i range.
   *    We slide R relative to L.
   */

  best_corr = 0;
  best_d = 0;

  for (d = -CORR_LAG_MAX; d <= CORR_LAG_MAX; d++)
    {
      int32_t acc = 0;
      int start;
      int end;
      int idx;

      /* Valid overlap: i ∈ [max(0,d), min(n, n+d)) */

      start = (d > 0) ? d : 0;
      end   = (d > 0) ? n : n + d;

      for (idx = start; idx < end; idx++)
        {
          acc += (int32_t)g_mic_left[idx] *
                 (int32_t)g_mic_right[idx - d];
        }

      /* Normalise by geometric mean of energies to handle
       * gain mismatch (476 vs 803).  Use shift to avoid overflow.
       */

      denom = (energy_l >> 8) * (energy_r >> 8);
      if (denom > 0)
        {
          /* Scale acc to comparable range */

          acc = (int32_t)(((int64_t)acc << 16) / denom);
        }

      if (d == -CORR_LAG_MAX || acc > best_corr)
        {
          best_corr = acc;
          best_d = d;
        }
    }

  syslog(LOG_INFO,
         "[hear] peak lag d*=%d  corr=%ld\n",
         best_d, (long)best_corr);

  /* e) Parabolic interpolation: fit parabola to (d*-1, d*, d*+1)
   *    τ = d* + (corr[d*-1] - corr[d*+1]) / (2 * (corr[d*-1] - 2*corr[d*] + corr[d*+1]))
   *    Result in Q8 fixed-point.
   */

  /* Re-compute the three correlation values around peak.
   * (We kept best_corr but need neighbours.)
   */

  {
    int32_t c[3]; /* c[0]=corr(d*-1), c[1]=corr(d*), c[2]=corr(d*+1) */

    for (i = 0; i < 3; i++)
      {
        int dd = best_d - 1 + i;
        int32_t acc = 0;
        int start2;
        int end2;
        int idx2;

        start2 = (dd > 0) ? dd : 0;
        end2   = (dd > 0) ? n : n + dd;

        for (idx2 = start2; idx2 < end2; idx2++)
          {
            acc += (int32_t)g_mic_left[idx2] *
                   (int32_t)g_mic_right[idx2 - dd];
          }

        denom = (energy_l >> 8) * (energy_r >> 8);
        if (denom > 0)
          {
            acc = (int32_t)(((int64_t)acc << 16) / denom);
          }

        c[i] = acc;
      }

    corr_prev = c[0];
    corr_best = c[1];
    corr_next = c[2];
  }

  /* Parabolic interpolation for sub-sample estimate */

  {
    int32_t num = corr_prev - corr_next; /* numerator */
    int32_t den = corr_prev - 2 * corr_best + corr_next; /* denominator * 2 */

    if (den != 0)
      {
        /* τ_frac = num / (2 * den), in Q8
         * τ = best_d + τ_frac
         * We compute τ in Q8: best_d * 256 + (num << 8) / (2 * den)
         */

        tau_q8 = (int32_t)best_d * 256 +
                 (int32_t)(((int64_t)num << 8) / (2 * den));
      }
    else
      {
        /* Flat top — no interpolation possible */

        tau_q8 = (int32_t)best_d * 256;
      }
  }

  syslog(LOG_INFO,
         "[hear] tau_q8=%ld (%.2f samples)\n",
         (long)tau_q8, (double)tau_q8 / 256.0);

  /* f) Map to direction */

  if (tau_q8 < -TAU_DEAD_Q8)
    {
      dx = DX_LEFT;
    }
  else if (tau_q8 > TAU_DEAD_Q8)
    {
      dx = DX_RIGHT;
    }
  else
    {
      dx = DX_CENTER;
    }

  syslog(LOG_INFO,
         "[hear] direction: %s (dx=%d)\n",
         dx < 0 ? "LEFT" : dx > 0 ? "RIGHT" : "CENTER",
         dx);

  if (out_tau_q8)
    {
      *out_tau_q8 = (int)tau_q8;
    }

  return dx;
}

/****************************************************************************
 * Name: bk7258_mic_main
 *
 * Description:
 *   NSH command: lcdtest mic — ADC dual-channel capture + RMS dump.
