/****************************************************************************
 * Name: lcdtest_hear
 *
 * Description:
 *   Sound localization: capture stereo audio, estimate direction via
 *   cross-correlation, drive eye_look() to look toward the sound.
 *   Prints RMS, peak lag d*, interpolated τ, and direction for calibration.
 *
 ****************************************************************************/

static int lcdtest_hear(void)
{
  int tau_q8;
  int dx;

  /* Ensure LCD is up with eye drawn */

  lcdtest_go();

  syslog(LOG_INFO,
         "[hear] === sound localization test ===\n");

  dx = bk7258_mic_locate(&tau_q8);

  syslog(LOG_INFO,
         "[hear] result: dx=%d  tau_q8=%d (%.2f samples)\n",
         dx, tau_q8, (double)tau_q8 / 256.0);

  /* Drive eye toward detected direction */

  eye_look(dx);

  syslog(LOG_INFO,
         "[hear] eye_look(%d) done\n", dx);

  return OK;
}

