/****************************************************************************
 * Official-website-style eye: white bg + blue iris + black eyelids
 *
 * Color palette (RGB565):
 *   0xFFFF  white  (background)
 *   0x02DF  sky-blue (iris) — try 0x001F for deeper blue
 *   0x0000  black  (pupil, eyelids)
 *   0xFFFF  white  (highlight)
 ****************************************************************************/

#define OEYE_BG        0xFFFF  /* white */
#define OEYE_IRIS      0x02DF  /* sky-blue */
#define OEYE_PUPIL     0x0000  /* black */
#define OEYE_HL        0xFFFF  /* white highlight */
#define OEYE_LID       0x0000  /* black eyelid */

#define OEYE_IRIS_R    52
#define OEYE_PUPIL_R   24
#define OEYE_HL_R      8
#define OEYE_HL_X      66     /* highlight centre */
#define OEYE_HL_Y      66

/****************************************************************************
 * Name: draw_oeye_base
 *
 * Description:
 *   Draw the base oeye: white background, blue iris, black pupil,
 *   white highlight.  Called once per panel, then eyelids are
 *   layered on top.
 *
 ****************************************************************************/

static void draw_oeye_base(void)
{
  /* 1) White background — full screen */

  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, OEYE_BG);

  /* 2) Blue iris */

  lcd_fill_circle(80, 80, OEYE_IRIS_R, OEYE_IRIS);

  /* 3) Black pupil */

  lcd_fill_circle(80, 80, OEYE_PUPIL_R, OEYE_PUPIL);

  /* 4) White highlight (upper-left) */

  lcd_fill_circle(OEYE_HL_X, OEYE_HL_Y, OEYE_HL_R, OEYE_HL);
}

/****************************************************************************
 * Name: eye_o_neutral
 *
 * Description:
 *   Neutral / open: draw base eye then thin black eyelid borders
 *   top and bottom, leaving most of the blue iris visible.
 *
 ****************************************************************************/

static void eye_o_neutral(void)
{
  draw_oeye_base();

  /* Upper eyelid: thin black strip at top, curved inward.
   * Use a large-radius circle centred above the screen to carve
 *   an arc.  Simplest: just fill a rect for now (draft).
   */

  lcd_fill_rect(0, 0, LCD_WIDTH - 1, 8, OEYE_LID);

  /* Lower eyelid */

  lcd_fill_rect(0, LCD_HEIGHT - 9, LCD_WIDTH - 1, LCD_HEIGHT - 1,
                OEYE_LID);
}

/****************************************************************************
 * Name: eye_o_blink
 *
 * Description:
 *   Blink / closed: black eyelids cover most of the iris.
 *   Just fill the whole screen black (or leave a thin seam).
