  lcd_fill_rect(0, 86, LCD_WIDTH - 1, LCD_HEIGHT - 1, OEYE_LID);

  /* Thin seam in the middle — keep whatever was there (iris edge) */

}

/****************************************************************************
 * Name: eye_o_happy
 *
 * Description:
 *   Happy expression: base eye + lower eyelid pushed up into a
 *   curved smile (◡ shape).  Upper eyelid stays thin.
 *
