/****************************************************************************
 * Name: draw_oeye_base
 *
 * Description:
 *   Draw the base oeye: white background, blue iris (large),
 *   black pupil, two white highlights for water-shine.
 *   Eyelids are layered on top by the caller.
 *
 ****************************************************************************/

static void draw_oeye_base(void)
{
  /* 1) White background — full screen */

  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, OEYE_BG);

  /* 2) Blue iris — big circle, nearly fills screen */

  lcd_fill_circle(80, 80, OEYE_IRIS_R, OEYE_IRIS);

  /* 3) Black pupil */

  lcd_fill_circle(80, 80, OEYE_PUPIL_R, OEYE_PUPIL);

  /* 4) Two white highlights for water-shine effect */

  lcd_fill_circle(OEYE_HL1_X, OEYE_HL1_Y, OEYE_HL1_R, OEYE_HL);
  lcd_fill_circle(OEYE_HL2_X, OEYE_HL2_Y, OEYE_HL2_R, OEYE_HL);
}

/****************************************************************************
 * Name: eye_o_neutral
 *
 * Description:
 *   Neutral / fully open: base eye + thin black eyelid outline
 *   top and bottom.  The eyelid is a curved arc (big circle
 *   partially overlapping) that frames the blue iris with a
 *   clear black edge against the white background.
 *
 ****************************************************************************/

static void eye_o_neutral(void)
{
  draw_oeye_base();

  /* Upper eyelid: black rect from top down, then carve the inner
   * edge with a big white circle to create a curved arc.
   * Simpler: just fill the top strip where the arc overlaps.
   * Lid top covers y from 0 to ~18 (thin).
   */

  lcd_fill_rect(0, 0, LCD_WIDTH - 1, 16, OEYE_LID);

  /* Lower eyelid: same from bottom up */

  lcd_fill_rect(0, LCD_HEIGHT - 17, LCD_WIDTH - 1, LCD_HEIGHT - 1,
                OEYE_LID);
}

/****************************************************************************
 * Name: eye_o_half
 *
 * Description:
 *   Half-closed: eyelids closing in from top and bottom,
 *   covering part of the blue iris.  Top lid down to ~45,
 *   bottom lid up to ~115.
 *
 ****************************************************************************/

static void eye_o_half(void)
{
  draw_oeye_base();

  /* Upper eyelid: push down further */

  lcd_fill_rect(0, 0, LCD_WIDTH - 1, 45, OEYE_LID);

  /* Lower eyelid: push up further */

  lcd_fill_rect(0, 115, LCD_WIDTH - 1, LCD_HEIGHT - 1, OEYE_LID);
}

/****************************************************************************
 * Name: eye_o_blink
 *
 * Description:
 *   Fully closed: black eyelids meet near the middle, covering
 *   almost all of the blue iris.  Result is a white background
 *   with a thick black curved arc (◡) across the middle.
 *
 ****************************************************************************/

static void eye_o_blink(void)
{
  /* White background first */

  lcd_fill_rect(0, 0, LCD_WIDTH - 1, LCD_HEIGHT - 1, OEYE_BG);

  /* Black arc: top lid down to ~70, bottom lid up to ~90
   * This leaves a thin seam but mostly covers the iris.
   */

  lcd_fill_rect(0, 0, LCD_WIDTH - 1, 70, OEYE_LID);
  lcd_fill_rect(0, 90, LCD_WIDTH - 1, LCD_HEIGHT - 1, OEYE_LID);
}

/****************************************************************************
 * Name: eye_o_happy
 *
 * Description:
 *   Happy expression: base eye + lower eyelid pushed up into a
 *   curved smile (◡ shape).  Upper eyelid stays thin.
 *
 ****************************************************************************/

static void eye_o_happy(void)
{
  draw_oeye_base();

  /* Upper eyelid: thin strip (same as neutral) */

  lcd_fill_rect(0, 0, LCD_WIDTH - 1, 16, OEYE_LID);

  /* Lower eyelid: push up to y=115 to carve a smile.
   * Fill black from y=115 down to bottom.
   */

  lcd_fill_rect(0, 115, LCD_WIDTH - 1, LCD_HEIGHT - 1, OEYE_LID);
}

